---@class GoFishEndState
local GoFishEndState = Class("GoFishEndState", GoFishBaseState)

function GoFishEndState.new(luaDialog)
    local instance = GoFishEndState.New()
    instance.luaDialog = luaDialog
    instance.TransferTo = luaDialog.TransferTo
    for k, v in pairs(luaDialog) do
        instance[k] = v
    end
    return instance
end

function GoFishEndState:CanTransfer(target)
    if target == EGoFishState.Ready then
        return true
    else
        return false
    end
end

function GoFishEndState:OnEnter(body)
