function GoFishEndState:Update()
    if self and not isNull(self.fishLineServer) then
        self.fishLineServer:OnUpdate()
    end
end

function GoFishEndState:OnExit()
end

--失败表现
function GoFishEndState:FillFailInfo(type)
    self:ClearFailCo()
    KTool.SetActive(self.FishFailTipsGroup, true)

    local resultStr, textContentStr = "", ""
    if type == ConstantsFishing.FishFinishType.BreakLine then
        resultStr = localize("鱼线断了")
        textContentStr = localize("请控制力度")
    elseif type == ConstantsFishing.FishFinishType.BreakFree then
        resultStr = localize("鱼儿跑了")
        textContentStr = localize("请控制力度")
    elseif type == ConstantsFishing.FishFinishType.DisExceed then
        resultStr = localize("鱼线断了")
        textContentStr = localize("请换用更长的鱼线")
    end
    CfUtils.FillText(self.TextTitle, resultStr)
    CfUtils.FillText(self.TextContent, textContentStr)
    self._failCo = cs_coroutine.start(function()
        CfUtils.PlayAnimator(self.AnimRoot, "Play")
        coroutine.yield(WaitForSeconds(2))
        KTool.SetActive(self.FishFailTipsGroup, false)
    end)
end

function GoFishEndState:ClearFailCo()
    if self._getFishCo then
        cs_coroutine.stop(self._getFishCo)
        self._getFishCo = nil
    end

    if self._failCo then
        cs_coroutine.stop(self._failCo)
        self._failCo = nil
    end

    if self._castCo then
        cs_coroutine.stop(self._castCo)
        self._castCo = nil
    end
end

--关闭界面的回调
function GoFishEndState:OnCloseGetDialog(lastExp, lastLevel)
    self._getFishCo = cs_coroutine.start(function()
        --CfUtils.PlayAnimator(self.ImgCreel, "Play")

        local curLevel, curExp = FishingUtils.GetCurLevelAndExp()
        --升级
        if checkNumber(curLevel) > lastLevel then
            local needExp = FishingUtils.GetUpLevelExp(lastLevel)

            local showExp = FishingUtils.GetShowExpByLevelAndExp(lastLevel, lastExp)
            local dis = needExp - showExp
            CfUtils.DoTween(0.4, function(value)
                local showExp = showExp + dis * value
                self.ImgRound.fillAmount = showExp/needExp --0.15 + showExp/needExp * (0.84 - 0.15)
            end)
            coroutine.yield(WaitForSeconds(0.4))
            CfUtils.FillText(self.TxtLv, curLevel)

            local needExp = FishingUtils.GetUpLevelExp(curLevel)
            local dis = FishingUtils.GetShowExpByLevelAndExp(curLevel, curExp)

            CfUtils.DoTween(0.8, function(value)
                local showExp = 0 + dis * value
                self.ImgRound.fillAmount = showExp/needExp --0.15 + showExp/needExp * (0.84 - 0.15)
            end)
        else
            local needExp = FishingUtils.GetUpLevelExp(curLevel)

            local dis = curExp - lastExp
            local showExp = FishingUtils.GetShowExpByLevelAndExp(lastLevel, lastExp)
            CfUtils.DoTween(0.8, function(value)
                local showExp = showExp + dis * value
                self.ImgRound.fillAmount = showExp/needExp --0.15 + showExp/needExp * (0.84 - 0.15)
            end)
        end
    end)
end

--结束时候动作的参数
function GoFishEndState:GetFinishStatusNum(type, forceScale, data)
    if type == ConstantsFishing.FishFinishType.BreakLine or type == ConstantsFishing.FishFinishType.DisExceed then
        return 41, 3.633
    elseif type == ConstantsFishing.FishFinishType.BreakFree then
        return 51, 3.333
    else
        local num = checkInt(forceScale / 0.75) + 1

        local isS = (FishingUtils.GetFishRareNameByRare(data.rating) == "S")
        if isS then
            --新获得
            --if checkNumber(data.isNew) == 1  then
            return 110 + num, 3.933
            --新纪录
            --elseif checkNumber(data.isNew) == 1  then
            --    return 120 + num, 3.933
            --else
            --    return 130 + num, 3.933
            --end
        else
            --新获得
            --if checkNumber(data.isNew) == 1  then
            return 10 + num, 2.467
            --新纪录
            --elseif checkNumber(data.isNew) == 1  then
            --    return 20 + num, 2.467
            --else
            --    return 30 + num, 2.467
            --end
        end
    end
    return 10, 2.467
end

return GoFishEndState